import React, { useMemo, useState } from 'react';
import { AlertTriangle, ChevronDown, ChevronRight, MapPin, PlusCircle, Search, Sparkles, X } from 'lucide-react';
import { SERVICE_CATEGORIES } from '../../data/categories';
import { DEMO_SERVICES } from '../../data/demoServices';
import { ServiceCategoryId, ServiceItem } from '../../types';
import { CategoryIcon } from '../common/CategoryIcon';
import { DemoBanner } from '../common/DemoBanner';

interface CustomerHomeProps {
    selectedLocality: string;
      onOpenLocationModal: () => void;
        onSelectService: (service: ServiceItem, emergency?: boolean) => void;
          onOpenOtherService: (initialQuery?: string) => void;
}

export const CustomerHome: React.FC<CustomerHomeProps> = ({
    selectedLocality,
      onOpenLocationModal,
        onSelectService,
          onOpenOtherService,
}) => {
    const [searchQuery, setSearchQuery] = useState('');
      const [activeCategory, setActiveCategory] = useState<ServiceCategoryId | 'all'>('all');
        const [showEmergencyPicker, setShowEmergencyPicker] = useState(false);

          const emergencyServices = useMemo(() => {
                const emergencyCats = new Set(SERVICE_CATEGORIES.filter((c) => c.isEmergencyEligible).map((c) => c.id));
                    return DEMO_SERVICES.filter((s) => emergencyCats.has(s.categoryId));
          }, []);

            const filteredServices = useMemo(() => {
                  const q = searchQuery.trim().toLowerCase();
                      return DEMO_SERVICES.filter((srv) => {
                              if (activeCategory !== 'all' && srv.categoryId !== activeCategory) return false;
                                    if (!q) return true;
                                          const catName = SERVICE_CATEGORIES.find((c) => c.id === srv.categoryId)?.name.toLowerCase() ?? '';
                                                return srv.title.toLowerCase().includes(q) || srv.description.toLowerCase().includes(q) || catName.includes(q);
                      });
            }, [searchQuery, activeCategory]);

              const handleCategoryClick = (catId: ServiceCategoryId) => {
                    if (catId === 'other') {
                            onOpenOtherService();
                                  return;
                    }
                        setActiveCategory((prev) => (prev === catId ? 'all' : catId));
              };

                return (
                      <div className="flex-1 flex flex-col pb-4">
                            <header className="bg-navy-800 text-white px-4 pt-4 pb-5 rounded-b-3xl shadow-md safe-top">
                                    <div className="flex items-center justify-between gap-2 mb-3">
                                              <div>
                                                          <div className="flex items-center gap-1.5">
                                                                        <span className="text-lg font-extrabold tracking-tight">NEED<span className="text-teal-400">ZO</span></span>
                                                                                      <span className="text-[10px] px-2 py-0.5 rounded-full bg-white/10 text-teal-300 font-medium">Bhopal</span>
                                                                                                  </div>
                                                                                                              <p className="text-[11px] text-slate-300">Har Zaroorat Ka Solution</p>
                                                                                                                        </div>
                                                                                                                                  <button type="button" onClick={onOpenLocationModal} className="flex items-center gap-1.5 max-w-[195px] bg-white/10 hover:bg-white/15 border border-white/15 px-3 py-1.5 rounded-full text-xs font-medium">
                                                                                                                                              <MapPin className="w-3.5 h-3.5 text-teal-400 shrink-0" />
                                                                                                                                                          <span className="truncate">{selectedLocality}</span>
                                                                                                                                                                      <ChevronDown className="w-3.5 h-3.5 text-slate-300 shrink-0" />
                                                                                                                                                                                </button>
                                                                                                                                                                                        </div>

                                                                                                                                                                                                <div className="relative">
                                                                                                                                                                                                          <Search className="w-4 h-4 text-slate-400 absolute left-3.5 top-1/2 -translate-y-1/2" />
                                                                                                                                                                                                                    <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Search plumber, AC, cook, tutor, shifting..." className="w-full pl-10 pr-9 py-2.5 rounded-xl bg-white text-slate-900 text-sm placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-teal-400" />
                                                                                                                                                                                                                              {searchQuery && (
                                                                                                                                                                                                                                            <button type="button" onClick={() => setSearchQuery('')} aria-label="Clear search" className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400">
                                                                                                                                                                                                                                                          <X className="w-4 h-4" />
                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                            </header>

                                                                                                                                                                                                                                                  <div className="px-4 pt-4 space-y-5">
                                                                                                                                                                                                                                                          <DemoBanner compact />

                                                                                                                                                                                                                                                                  <button type="button" onClick={() => setShowEmergencyPicker(true)} className="w-full text-left rounded-2xl bg-gradient-to-r from-rose-600 to-rose-700 text-white p-4 shadow-sm flex items-center justify-between gap-3">
                                                                                                                                                                                                                                                                            <div className="flex items-start gap-3">
                                                                                                                                                                                                                                                                                        <div className="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center shrink-0"><AlertTriangle className="w-5 h-5" /></div>
                                                                                                                                                                                                                                                                                                    <div>
                                                                                                                                                                                                                                                                                                                  <div className="flex items-center gap-2"><span className="text-sm font-bold">Emergency Booking</span><span className="text-[10px] font-semibold uppercase px-1.5 py-0.5 rounded bg-white/20">Urgent</span></div>
                                                                                                                                                                                                                                                                                                                                <p className="text-xs text-rose-100 mt-0.5">Pipe burst, power outage, lock jammed or AC breakdown in Bhopal</p>
                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                <ChevronRight className="w-5 h-5 text-rose-100 shrink-0" />
                                                                                                                                                                                                                                                                                                                                                                        </button>

                                                                                                                                                                                                                                                                                                                                                                                <section>
                                                                                                                                                                                                                                                                                                                                                                                          <div className="flex items-center justify-between mb-3">
                                                                                                                                                                                                                                                                                                                                                                                                      <h2 className="text-sm font-bold text-navy-800">All Categories</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                  {activeCategory !== 'all' && <button type="button" onClick={() => setActiveCategory('all')} className="text-xs font-semibold text-teal-600">Show All</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="grid grid-cols-4 gap-2.5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                  {SERVICE_CATEGORIES.map((cat) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const selected = activeCategory === cat.id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const isOther = cat.id === 'other';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button key={cat.id} type="button" onClick={() => handleCategoryClick(cat.id)} className={`flex flex-col items-center justify-start p-2.5 rounded-2xl border text-center transition min-h-[86px] ${selected ? 'bg-navy-800 text-white border-navy-800 shadow-sm' : isOther ? 'bg-teal-50 text-navy-800 border-teal-200' : 'bg-white text-navy-800 border-slate-200'}`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className={`w-9 h-9 rounded-xl flex items-center justify-center mb-1.5 ${selected ? 'bg-teal-500 text-white' : isOther ? 'bg-teal-600 text-white' : 'bg-navy-50 text-navy-800'}`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <CategoryIcon categoryId={cat.id} className="w-4 h-4" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <span className="text-[11px] font-semibold leading-tight line-clamp-2">{cat.name}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                  })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </section>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="rounded-2xl bg-navy-800 text-white p-4 flex items-center justify-between gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="flex items-center gap-1.5 text-teal-300 text-xs font-semibold"><Sparkles className="w-3.5 h-3.5" />Unlisted Need?</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="text-sm font-bold mt-0.5">Request Any Other Service</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="text-[11px] text-slate-300 mt-0.5">Pest control, tank cleaning, welder, gardener, or custom help</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button type="button" onClick={() => onOpenOtherService(searchQuery)} className="px-3.5 py-2 rounded-xl bg-teal-500 text-navy-900 text-xs font-bold shrink-0 flex items-center gap-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <PlusCircle className="w-4 h-4" />Request
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <section className="space-y-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="flex items-center justify-between">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h2 className="text-sm font-bold text-navy-800">{activeCategory === 'all' ? 'Popular Services in Bhopal' : `${SERVICE_CATEGORIES.find((c) => c.id === activeCategory)?.name} Services`}</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <span className="text-[10px] font-semibold uppercase px-2 py-0.5 rounded-full bg-slate-200 text-slate-600">Demo Rates</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {filteredServices.length === 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="bg-white rounded-2xl border border-slate-200 p-5 text-center space-y-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="text-sm font-semibold text-navy-800">No listed service matches "{searchQuery}"</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button type="button" onClick={() => onOpenOtherService(searchQuery)} className="px-4 py-2.5 rounded-xl bg-teal-600 text-white text-xs font-semibold">Request "{searchQuery || 'Custom Service'}"</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="space-y-2.5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {filteredServices.map((srv) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div key={srv.id} className="bg-white rounded-2xl border border-slate-200 p-3.5 shadow-sm flex items-start justify-between gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="flex items-start gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="w-10 h-10 rounded-xl bg-teal-50 text-teal-700 flex items-center justify-center shrink-0 mt-0.5"><CategoryIcon categoryId={srv.categoryId} className="w-5 h-5" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h3 className="text-sm font-bold text-navy-800">{srv.title}</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="text-xs text-slate-600 mt-0.5 line-clamp-2">{srv.description}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="flex items-center gap-2 mt-2 text-[11px]">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span className="font-bold text-navy-800">Est. Visit ₹{srv.estimatedVisitFee}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span className="text-slate-400">•</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span className="text-slate-500">{srv.estimatedDuration}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span className="text-[10px] px-1.5 py-0.5 rounded bg-slate-100 text-slate-500">Demo</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button type="button" onClick={() => onSelectService(srv, false)} className="px-3 py-2 rounded-xl bg-navy-800 text-white text-xs font-semibold shrink-0 self-center">Book</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {showEmergencyPicker && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="fixed inset-0 z-50 bg-navy-900/60 flex items-end sm:items-center justify-center">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="w-full max-w-[430px] bg-white rounded-t-3xl sm:rounded-2xl max-h-[80vh] flex flex-col">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="flex items-center justify-between px-5 py-4 border-b border-slate-100">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="flex items-center gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <AlertTriangle className="w-5 h-5 text-rose-600" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <h3 className="text-sm font-bold text-navy-800">Emergency Priority Request</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="text-[11px] text-slate-500">Select urgent issue in {selectedLocality}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button type="button" onClick={() => setShowEmergencyPicker(false)} className="p-2 rounded-full hover:bg-slate-100 text-slate-500"><X className="w-5 h-5" /></button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="p-4 space-y-2.5 overflow-y-auto">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded-xl px-3 py-2">Demo Notice: Emergency requests tag your booking as High Priority for nearby partners in Bhopal.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {emergencyServices.map((srv) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button key={srv.id} type="button" onClick={() => { setShowEmergencyPicker(false); onSelectService(srv, true); }} className="w-full text-left p-3.5 rounded-xl border border-rose-200 bg-rose-50/40 flex items-center justify-between gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="flex items-center gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="w-9 h-9 rounded-lg bg-rose-100 text-rose-700 flex items-center justify-center shrink-0"><CategoryIcon categoryId={srv.categoryId} className="w-4 h-4" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="text-sm font-bold text-navy-800">{srv.title}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p className="text-[11px] text-slate-600">Est. Visit ₹{srv.estimatedVisitFee} • Urgent Slot</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <ChevronRight className="w-4 h-4 text-rose-600 shrink-0" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                );
};
